public class WarehouseInfo
{
    public string Id { get; set; } = "WH-A";
    public string Name { get; set; } = "Warehouse A";

    public static readonly WarehouseInfo[] All =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];
}

namespace sv_b28f7a64ee9448429aaa7695fb565773.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// Components subscribe to <see cref="OnAlertCountChanged"/> to stay
/// synchronized when any component triggers a refresh.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="RefreshAlertCountAsync"/> completes.
    /// Subscribers should wrap StateHasChanged in InvokeAsync because
    /// this event fires from a timer (background thread).
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest alert count and notifies all subscribers.
    /// Called by the polling component; updates are visible to every
    /// component that subscribes to <see cref="OnAlertCountChanged"/>.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        LastAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

