    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_b28f7a64ee9448429aaa7695fb565773.Models
@using sv_b28f7a64ee9448429aaa7695fb565773.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <h5 class="mb-0">Current Warehouse: @Warehouse?.Name</h5>
    </div>
    <div class="card-body">
        <p>Warehouse ID: <code>@Warehouse?.Id</code></p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-header d-flex align-items-center">
        <h5 class="mb-0">Low-Stock Alerts</h5>
        <span class="badge @(AlertService.LastAlertCount > 0 ? "bg-danger" : "bg-success") ms-2 fs-6">
            @AlertService.LastAlertCount
        </span>
    </div>
    <div class="card-body">
        @if (AlertService.LastAlertCount > 0)
        {
            <div class="alert alert-warning mb-0">
                ⚠️ <strong>@AlertService.LastAlertCount item(s)</strong> are below minimum stock levels
                at <strong>@Warehouse?.Name</strong>. Polling every 10 seconds.
            </div>
        }
        else
        {
            <div class="alert alert-success mb-0">
                ✅ All items are at or above minimum stock levels. Polling every 10 seconds.
            </div>
        }
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private Timer? _pollingTimer;
    private Action? _alertHandler;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        _cts = new CancellationTokenSource();
        _pollingTimer = new Timer(async _ =>
        {
            if (_cts?.IsCancellationRequested == true) return;
            var warehouseId = Warehouse?.Id ?? WarehouseInfo.All[0].Id;
            await AlertService.RefreshAlertCountAsync(warehouseId);
        }, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    protected override void OnParametersSet()
    {
        // When the warehouse cascading parameter changes, refresh immediately
        if (Warehouse is not null)
        {
            _ = AlertService.RefreshAlertCountAsync(Warehouse.Id);
        }
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _pollingTimer?.Dispose();
    }
}

